size(120);
add(grid(8,8));
draw((0,0)--(8,0),linewidth(1.2));
draw((0,0)--(0,8),linewidth(1.2));
label("$x$",(8,0),E);
label("$y$",(0,8),N);
draw((0,5)--(3,0),Arrows);
draw((0,2)--(7,0),Arrows);
label("$l$",(0,5)--(3,0),NE);
label("$m$",(0,3)--(7,0),NE);
[/asy]

